```c
int marks[] = {7, 9, 8, 6, 10};
size_t count = sizeof marks / sizeof marks[0];   /* 5. */

/* Counted loop: indexes 0..count-1. */
int total = 0;
for (size_t i = 0; i < count; i++) {
    total += marks[i];
}

/* Sentinel loop: stop at the first negative value. */
int data[] = {4, 2, 5, -1};
size_t j = 0;
while (data[j] >= 0) {
    j++;                       /* progress toward the sentinel. */
}

/* do-while: show the menu at least once. */
int choice;
do {
    choice = read_choice();
} while (choice != 0);
```

